SELECT a.SEC_SNAME AS `股票名称`, a.SEC_CODE AS `股票代码`, b.ENDDATE AS `报表截止日`, ROUND(b.F110101 / 10000, 1) AS `归母净利润(万元)` FROM GET_A_SEC_CODE a INNER JOIN VIEW_STK_FIN_IDX b ON a.COMCODE = b.COMCODE WHERE a.SEC_SNAME LIKE '%兴业银行%' AND b.ENDDATE = '2025-12-31 00:00:00' AND b.ISVALID = 1 AND a.ISVALID = 1 AND b.F110101 IS NOT NULL ORDER BY b.ENDDATE DESC LIMIT 1;
